import React, { useState } from "react";

export function ToastSnackbar() {
  const [visible, setVisible] = useState(true);
  return (
    <div className="w-full max-w-sm">
      {visible ? (
        <div role="status" className="flex items-center justify-between gap-3 p-3 rounded-lg border border-border bg-card shadow-md text-xs">
          <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-emerald-500" /><span className="text-foreground font-medium">Changes saved successfully</span></div>
          <button onClick={() => setVisible(false)} className="text-muted-foreground hover:text-foreground text-xs px-1" aria-label="Dismiss toast">✕</button>
        </div>
      ) : (
        <button onClick={() => setVisible(true)} className="px-3 py-1.5 rounded-[8px] border border-border text-xs text-muted-foreground hover:text-foreground">Trigger notification</button>
      )}
    </div>
  );
}
